/* PULSAR — Neon Arena */

:root {
  --bg: #04050b;
  --ink: #e9f4ff;
  --muted: #8ea4c6;
  --faint: #5b6b8a;
  --line: rgba(148, 186, 255, 0.15);
  --line-soft: rgba(148, 186, 255, 0.08);
  --cyan: #5ef2ff;
  --magenta: #ff54be;
  --violet: #9d8bff;
  --amber: #ffb75e;
  --green: #6dffb0;
  --red: #ff5f6d;
  --panel: rgba(8, 12, 24, 0.78);
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", "Segoe UI Mono", "Roboto Mono", Menlo, Consolas, monospace;
  --sans: "Inter Tight", "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior: none;
}

body { user-select: none; -webkit-user-select: none; }

#game {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  background: var(--bg);
}

body.playing #game { cursor: none; }

/* ------------------------------------------------------------------ FX */

.fx { position: fixed; inset: 0; pointer-events: none; z-index: 5; }

.fx-grid-glow {
  background:
    radial-gradient(ellipse 70% 45% at 50% -8%, rgba(94, 242, 255, 0.12), transparent 70%),
    radial-gradient(ellipse 50% 40% at 92% 108%, rgba(255, 84, 190, 0.09), transparent 70%);
  mix-blend-mode: screen;
}

.fx-vignette {
  background: radial-gradient(ellipse 82% 78% at 50% 48%, transparent 40%, rgba(2, 4, 10, 0.55) 78%, rgba(2, 3, 8, 0.9) 100%);
}

.fx-scan {
  background: repeating-linear-gradient(to bottom, rgba(255, 255, 255, 0.035) 0 1px, transparent 1px 3px);
  opacity: 0.35;
  mix-blend-mode: overlay;
}

/* ------------------------------------------------------------------ HUD */

.hud {
  position: fixed;
  inset: 0;
  z-index: 20;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: start;
  gap: 20px;
  padding: 20px 24px;
  pointer-events: none;
  font-family: var(--mono);
  opacity: 0;
  transform: translateY(-8px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

body.playing .hud, body.dead .hud { opacity: 1; transform: none; }

.hud-col { display: flex; flex-direction: column; pointer-events: none; }
.hud-left { align-items: flex-start; gap: 14px; }
.hud-center { align-items: center; gap: 2px; padding-top: 2px; }
.hud-right { align-items: flex-end; gap: 12px; }

.brand { display: flex; align-items: center; gap: 10px; }
.brand-mark {
  width: 22px; height: 22px; position: relative; display: grid; place-items: center;
  border: 1px solid rgba(94, 242, 255, 0.45);
  border-radius: 50%;
  box-shadow: 0 0 18px rgba(94, 242, 255, 0.25), inset 0 0 12px rgba(94, 242, 255, 0.15);
}
.brand-mark::before {
  content: ""; position: absolute; inset: 3px; border-radius: 50%;
  border: 1px dashed rgba(255, 84, 190, 0.55);
  animation: spin 9s linear infinite;
}
.brand-mark i {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--magenta);
  box-shadow: 0 0 10px var(--magenta), 0 0 22px rgba(255, 84, 190, 0.6);
}
@keyframes spin { to { transform: rotate(360deg); } }

.brand-word {
  font-family: var(--sans);
  font-weight: 800;
  font-size: 15px;
  letter-spacing: 0.34em;
  color: #dff8ff;
  display: flex; flex-direction: column; line-height: 1;
  text-shadow: 0 0 22px rgba(94, 242, 255, 0.35);
}
.brand-word em {
  font-style: normal; font-family: var(--mono); font-weight: 500;
  font-size: 7.5px; letter-spacing: 0.42em; color: var(--faint); margin-top: 5px;
}

.tag {
  font-size: 9px; letter-spacing: 0.26em; color: var(--muted);
}

.vitals { width: 268px; display: flex; flex-direction: column; gap: 6px; }
.vitals-head { display: flex; justify-content: space-between; align-items: baseline; }
.vitals-num { font-size: 11px; color: var(--muted); letter-spacing: 0.08em; }
.vitals-num b { font-size: 13px; color: var(--ink); font-weight: 600; }
.vitals-num i { font-style: normal; color: var(--faint); }

.bar {
  position: relative;
  background: rgba(140, 170, 220, 0.12);
  overflow: hidden;
  clip-path: polygon(0 0, 100% 0, calc(100% - 5px) 100%, 0 100%);
}
.hp-bar { height: 10px; box-shadow: inset 0 0 0 1px rgba(160, 200, 255, 0.12); }
.hp-fill, .hp-ghost {
  position: absolute; inset: 0 auto 0 0; width: 100%;
  transform-origin: left center;
}
.hp-fill {
  background: linear-gradient(90deg, #1fd7c0, #6dffb0 60%, #d9ffe9);
  box-shadow: 0 0 18px rgba(109, 255, 176, 0.45);
}
.hp-ghost {
  background: rgba(255, 95, 109, 0.55);
  transition: width 0.55s cubic-bezier(0.2, 0.8, 0.2, 1) 0.18s;
}
.hp-ticks {
  position: absolute; inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0 24px, rgba(4, 6, 12, 0.55) 24px 25px);
  opacity: 0.6;
}
.shield-row { display: flex; align-items: center; gap: 7px; }
.shield-glyph { font-size: 9px; color: var(--cyan); opacity: 0.9; text-shadow: 0 0 10px var(--cyan); }
.shield-bar { height: 3px; flex: 1; background: rgba(94, 242, 255, 0.12); }
.shield-bar div {
  height: 100%; width: 100%;
  background: linear-gradient(90deg, rgba(94, 242, 255, 0.5), var(--cyan));
  box-shadow: 0 0 12px rgba(94, 242, 255, 0.6);
  transition: width 0.12s linear;
}
.shield-num { font-size: 9px; color: var(--cyan); min-width: 22px; text-align: right; letter-spacing: 0.06em; }

.chips { display: flex; flex-wrap: wrap; gap: 5px; max-width: 268px; }
.chip {
  display: inline-flex; align-items: center; gap: 5px;
  height: 20px; padding: 0 7px;
  font-size: 9px; letter-spacing: 0.06em;
  color: rgba(232, 246, 255, 0.82);
  background: rgba(9, 15, 30, 0.66);
  border: 1px solid rgba(140, 180, 255, 0.16);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 4px), calc(100% - 4px) 100%, 0 100%);
  backdrop-filter: blur(6px);
}
.chip b { font-weight: 600; color: var(--cyan); font-size: 8px; }
.chip .chip-glyph { font-size: 10px; color: var(--cyan); text-shadow: 0 0 8px rgba(94, 242, 255, 0.7); }

.score-cap { font-size: 8.5px; letter-spacing: 0.5em; color: var(--faint); text-indent: 0.5em; }
.score {
  font-family: var(--mono);
  font-size: clamp(28px, 3.2vw, 44px);
  font-weight: 600;
  line-height: 1;
  letter-spacing: 0.06em;
  color: #f2fbff;
  text-shadow: 0 0 30px rgba(94, 242, 255, 0.4), 0 0 60px rgba(94, 242, 255, 0.16);
  font-variant-numeric: tabular-nums;
}
.combo-wrap { display: flex; align-items: center; gap: 8px; margin-top: 6px; }
.combo {
  font-size: 11px; color: var(--amber); letter-spacing: 0.12em;
  text-shadow: 0 0 14px rgba(255, 183, 94, 0.55);
}
.combo-bar { width: 54px; height: 2px; background: rgba(255, 183, 94, 0.16); }
.combo-bar i {
  display: block; height: 100%; width: 100%;
  background: linear-gradient(90deg, rgba(255, 183, 94, 0.4), var(--amber));
  box-shadow: 0 0 8px rgba(255, 183, 94, 0.7);
  transform-origin: left center;
}

.pills { display: flex; align-items: stretch; gap: 8px; }
.stat-pill {
  display: flex; flex-direction: column; align-items: flex-end; gap: 2px;
  min-width: 74px; padding: 7px 10px 6px;
  background: rgba(8, 13, 26, 0.6);
  border: 1px solid var(--line);
  border-top-color: rgba(94, 242, 255, 0.32);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 7px), calc(100% - 7px) 100%, 0 100%);
  backdrop-filter: blur(8px);
}
.stat-pill span { font-size: 8px; letter-spacing: 0.28em; color: var(--faint); }
.stat-pill b { font-size: 18px; line-height: 1; font-weight: 600; color: var(--ink); font-variant-numeric: tabular-nums; }
.stat-pill.dim { border-top-color: rgba(255, 183, 94, 0.3); min-width: 64px; }
.stat-pill.dim b { font-size: 13px; color: var(--amber); }

.hud-btns { display: flex; gap: 6px; pointer-events: auto; }
.icon-btn {
  width: 32px; height: 32px; display: grid; place-items: center;
  background: rgba(8, 13, 26, 0.62);
  border: 1px solid var(--line);
  color: var(--muted);
  cursor: pointer;
  transition: color 0.18s ease, border-color 0.18s ease, background 0.18s ease;
  backdrop-filter: blur(8px);
}
.icon-btn:hover { color: var(--cyan); border-color: rgba(94, 242, 255, 0.5); background: rgba(12, 24, 40, 0.8); }
.icon-btn svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.icon-btn .ico-off { display: none; }
.icon-btn.muted .ico-on { display: none; }
.icon-btn.muted .ico-off { display: block; }

/* ------------------------------------------------------------ boss HUD */

.boss-hud {
  position: fixed; z-index: 19; top: 118px; left: 50%;
  transform: translate(-50%, -12px);
  width: min(440px, 70vw);
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  opacity: 0; pointer-events: none;
  transition: opacity 0.5s ease, transform 0.5s ease;
  font-family: var(--mono);
}
.boss-hud.show { opacity: 1; transform: translate(-50%, 0); }
.boss-name { font-size: 9px; letter-spacing: 0.42em; color: rgba(255, 140, 220, 0.9); text-shadow: 0 0 14px rgba(255, 84, 190, 0.6); }
.boss-track {
  position: relative; width: 100%; height: 6px;
  background: rgba(255, 84, 190, 0.12);
  box-shadow: inset 0 0 0 1px rgba(255, 84, 190, 0.24);
  overflow: hidden;
}
.boss-track div {
  height: 100%; width: 100%;
  background: linear-gradient(90deg, #ff54be, #ff8f6b);
  box-shadow: 0 0 20px rgba(255, 84, 190, 0.7);
  transition: width 0.14s linear;
}
.boss-glint {
  position: absolute; inset: 0;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.45), transparent);
  width: 40%; animation: glint 2.4s ease-in-out infinite;
}
@keyframes glint { 0%, 100% { transform: translateX(-120%); } 55% { transform: translateX(320%); } }

/* ----------------------------------------------------------- dash meter */

.dash-readout {
  position: fixed; z-index: 18; left: 24px; bottom: 22px;
  display: flex; align-items: center; gap: 10px;
  font-family: var(--mono);
  opacity: 0; transition: opacity 0.4s ease;
  pointer-events: none;
}
body.playing .dash-readout { opacity: 1; }
.dash-ring {
  width: 38px; height: 38px; position: relative; border-radius: 50%;
  background: rgba(8, 13, 26, 0.65);
  border: 1px solid rgba(94, 242, 255, 0.24);
  display: grid; place-items: center;
  overflow: hidden;
}
.dash-ring i {
  position: absolute; left: 0; right: 0; bottom: 0; height: 100%;
  background: linear-gradient(180deg, rgba(94, 242, 255, 0.5), rgba(94, 242, 255, 0.12));
  transform-origin: bottom;
  transform: scaleY(1);
  transition: transform 0.1s linear;
}
.dash-ring::after {
  content: "⌁"; position: relative; color: #eafcff; font-size: 17px;
  text-shadow: 0 0 10px var(--cyan);
}
.dash-copy { display: flex; flex-direction: column; gap: 3px; }
.dash-copy kbd { font-family: var(--mono); font-size: 9px; letter-spacing: 0.16em; color: var(--cyan); }
.dash-copy span { font-size: 8px; letter-spacing: 0.34em; color: var(--faint); }
kbd {
  display: inline-block;
  padding: 3px 6px;
  font-family: var(--mono); font-size: 9px; letter-spacing: 0.12em;
  color: rgba(213, 234, 255, 0.86);
  background: rgba(12, 19, 36, 0.8);
  border: 1px solid rgba(148, 186, 255, 0.2);
  border-bottom-color: rgba(148, 186, 255, 0.32);
  border-radius: 3px;
}

.dash-btn {
  display: none;
  position: fixed; right: 20px; bottom: 26px; z-index: 30;
  width: 76px; height: 76px; border-radius: 50%;
  font-family: var(--mono); font-size: 10px; letter-spacing: 0.18em;
  color: #d9fbff;
  background: radial-gradient(circle at 35% 30%, rgba(94, 242, 255, 0.28), rgba(8, 14, 28, 0.85) 65%);
  border: 1px solid rgba(94, 242, 255, 0.45);
  box-shadow: 0 0 30px rgba(94, 242, 255, 0.22), inset 0 0 22px rgba(94, 242, 255, 0.12);
  touch-action: none;
}
body.touch.playing .dash-btn { display: block; }
body.touch .dash-readout { display: none; }

/* --------------------------------------------------------------- banner */

.banner {
  position: fixed; z-index: 22; left: 50%; top: 23%;
  transform: translate(-50%, -50%);
  display: flex; flex-direction: column; align-items: center; gap: 8px;
  pointer-events: none; opacity: 0;
  font-family: var(--mono);
}
.banner.show { animation: bannerIn 2.5s cubic-bezier(0.2, 0.7, 0.2, 1) forwards; }
@keyframes bannerIn {
  0% { opacity: 0; transform: translate(-50%, -50%) scale(0.94); filter: blur(6px); }
  12% { opacity: 1; transform: translate(-50%, -50%) scale(1); filter: blur(0); }
  78% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -50%) scale(1.03); }
}
.banner-line {
  width: 190px; height: 1px;
  background: linear-gradient(90deg, transparent, rgba(94, 242, 255, 0.7), transparent);
  box-shadow: 0 0 12px rgba(94, 242, 255, 0.4);
}
.banner-text {
  font-family: var(--sans);
  font-size: clamp(22px, 4vw, 40px);
  font-weight: 800;
  letter-spacing: 0.32em;
  text-indent: 0.32em;
  color: #f3fdff;
  text-shadow: 0 0 30px rgba(94, 242, 255, 0.55), 0 0 70px rgba(94, 242, 255, 0.2);
  white-space: nowrap;
}
.banner-sub {
  font-size: 9px; letter-spacing: 0.5em; text-indent: 0.5em;
  color: rgba(255, 84, 190, 0.9);
  text-transform: uppercase;
}

/* -------------------------------------------------------------- overlay */

.overlay {
  position: fixed; inset: 0; z-index: 40;
  display: grid; place-items: center;
  padding: 24px;
  background:
    radial-gradient(ellipse 60% 50% at 50% 40%, rgba(14, 24, 48, 0.5), transparent 70%),
    rgba(3, 5, 11, 0.72);
  backdrop-filter: blur(7px);
  opacity: 0; visibility: hidden;
  transition: opacity 0.35s ease, visibility 0.35s step-end;
  overflow-y: auto;
}
.overlay.show {
  opacity: 1; visibility: visible;
  transition: opacity 0.35s ease, visibility 0s;
}

.panel {
  position: relative;
  width: min(760px, 100%);
  padding: 40px 44px 34px;
  background:
    linear-gradient(160deg, rgba(20, 30, 54, 0.68), rgba(6, 9, 19, 0.9) 55%),
    rgba(5, 8, 18, 0.92);
  border: 1px solid rgba(140, 180, 255, 0.16);
  box-shadow:
    0 40px 120px -30px rgba(0, 0, 0, 0.9),
    inset 0 1px 0 rgba(170, 220, 255, 0.08),
    0 0 80px -20px rgba(94, 242, 255, 0.16);
  clip-path: polygon(0 0, calc(100% - 26px) 0, 100% 26px, 100% 100%, 26px 100%, 0 calc(100% - 26px));
  animation: panelIn 0.5s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
@keyframes panelIn {
  from { opacity: 0; transform: translateY(16px) scale(0.985); }
  to { opacity: 1; transform: none; }
}
.panel::before {
  content: ""; position: absolute; inset: 0;
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(94, 242, 255, 0.55), transparent 30%) top left / 160px 1px no-repeat,
    linear-gradient(180deg, rgba(94, 242, 255, 0.55), transparent 40%) top left / 1px 120px no-repeat,
    linear-gradient(270deg, rgba(255, 84, 190, 0.4), transparent 30%) bottom right / 140px 1px no-repeat;
}

.eyebrow {
  display: flex; align-items: center; gap: 8px;
  font-family: var(--mono); font-size: 9px; letter-spacing: 0.34em;
  color: var(--faint); text-transform: uppercase;
}
.eyebrow.center { justify-content: center; }
.dot {
  width: 5px; height: 5px; border-radius: 50%; background: var(--cyan);
  box-shadow: 0 0 10px var(--cyan); animation: pulse 2.2s ease-in-out infinite;
}
.dot.magenta { background: var(--magenta); box-shadow: 0 0 10px var(--magenta); }
.dot.red { background: var(--red); box-shadow: 0 0 10px var(--red); }
@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }

.title { margin: 20px 0 6px; display: flex; flex-direction: column; line-height: 0.86; }
.title-word {
  font-size: clamp(56px, 9.4vw, 106px);
  font-weight: 900;
  letter-spacing: 0.06em;
  background: linear-gradient(180deg, #ffffff 8%, #b9f6ff 44%, #5ef2ff 78%, #2aa8c8);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 26px rgba(94, 242, 255, 0.28)) drop-shadow(0 4px 0 rgba(255, 84, 190, 0.14));
}
.title-sub {
  font-style: normal; font-family: var(--mono);
  font-size: clamp(10px, 1.4vw, 13px); font-weight: 500;
  letter-spacing: 0.72em; text-indent: 0.72em;
  color: rgba(255, 84, 190, 0.9);
  margin-top: 14px;
  text-shadow: 0 0 20px rgba(255, 84, 190, 0.45);
}
.lede {
  max-width: 530px;
  margin: 20px 0 0;
  font-size: 13.5px; line-height: 1.65;
  color: var(--muted);
}
.lede b { color: var(--ink); font-weight: 600; }

.start-actions { display: flex; align-items: center; gap: 22px; margin-top: 30px; flex-wrap: wrap; }
.best-start {
  font-family: var(--mono); font-size: 9px; letter-spacing: 0.3em; color: var(--faint);
  display: flex; flex-direction: column; gap: 4px;
}
.best-start b { font-size: 20px; letter-spacing: 0.06em; color: var(--amber); font-weight: 600; text-shadow: 0 0 18px rgba(255, 183, 94, 0.4); }

.cta {
  position: relative;
  display: inline-flex; align-items: center; gap: 14px;
  padding: 16px 30px;
  font-family: var(--sans); font-size: 12.5px; font-weight: 800; letter-spacing: 0.22em;
  color: #041016;
  background: linear-gradient(100deg, #7cf6ff, #b6a6ff 52%, #ff7ecf);
  border: 0;
  cursor: pointer;
  clip-path: polygon(0 0, 100% 0, calc(100% - 15px) 100%, 0 100%);
  box-shadow: 0 10px 40px -10px rgba(94, 242, 255, 0.6);
  transition: transform 0.16s ease, filter 0.16s ease, box-shadow 0.16s ease;
  overflow: hidden;
}
.cta svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.cta:hover { transform: translateY(-2px); filter: brightness(1.08); box-shadow: 0 16px 50px -10px rgba(94, 242, 255, 0.75); }
.cta:active { transform: translateY(0) scale(0.99); }
.cta::after {
  content: ""; position: absolute; top: 0; bottom: 0; width: 40%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.65), transparent);
  transform: translateX(-160%) skewX(-18deg);
  animation: sweep 3.6s ease-in-out infinite;
}
@keyframes sweep { 0%, 62% { transform: translateX(-160%) skewX(-18deg); } 92%, 100% { transform: translateX(360%) skewX(-18deg); } }

.ghost-btn {
  padding: 14px 22px;
  font-family: var(--mono); font-size: 10px; letter-spacing: 0.2em;
  color: var(--muted);
  background: transparent;
  border: 1px solid rgba(148, 186, 255, 0.2);
  cursor: pointer;
  transition: color 0.18s ease, border-color 0.18s ease, background 0.18s ease;
}
.ghost-btn:hover { color: var(--ink); border-color: rgba(148, 186, 255, 0.45); background: rgba(255, 255, 255, 0.03); }

.how {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px; margin-top: 30px; padding-top: 22px;
  border-top: 1px solid var(--line-soft);
}
.how-item { display: flex; flex-direction: column; gap: 7px; align-items: flex-start; }
.how-item span { font-family: var(--mono); font-size: 8px; letter-spacing: 0.24em; color: var(--faint); text-transform: uppercase; }
.how-item kbd { min-width: 30px; text-align: center; }

.start-foot {
  display: flex; align-items: center; gap: 8px;
  margin-top: 22px;
  font-family: var(--mono); font-size: 8.5px; letter-spacing: 0.14em;
  color: var(--faint);
}
.live-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--green); box-shadow: 0 0 10px var(--green); animation: pulse 1.8s ease-in-out infinite; }

/* ---------------------------------------------------------- level panel */

.level-panel { width: min(880px, 100%); text-align: center; }
.panel-title {
  margin: 12px 0 0;
  font-size: clamp(26px, 3.6vw, 38px);
  font-weight: 800; letter-spacing: 0.16em; text-indent: 0.16em;
  color: #f4fcff;
  text-shadow: 0 0 34px rgba(94, 242, 255, 0.28);
}
.panel-sub { margin: 10px auto 0; max-width: 480px; font-size: 12px; line-height: 1.6; color: var(--muted); }
.cards { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 13px; margin: 28px 0 22px; }
.card {
  --accent: 94, 242, 255;
  position: relative;
  display: flex; flex-direction: column; align-items: flex-start;
  min-height: 208px;
  padding: 18px 16px 16px;
  font-family: var(--mono);
  text-align: left;
  color: var(--ink);
  background:
    radial-gradient(ellipse 90% 70% at 50% 0%, rgba(var(--accent), 0.13), transparent 65%),
    linear-gradient(165deg, rgba(255, 255, 255, 0.055), rgba(255, 255, 255, 0.012));
  border: 1px solid rgba(255, 255, 255, 0.12);
  cursor: pointer;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%);
  transition: transform 0.18s cubic-bezier(0.2, 0.8, 0.2, 1), box-shadow 0.18s ease, border-color 0.18s ease;
  overflow: hidden;
}
.card::before {
  content: ""; position: absolute; top: 0; left: 0; right: 0; height: 1px;
  background: linear-gradient(90deg, rgba(var(--accent), 0.95), rgba(var(--accent), 0.1));
}
.card:hover, .card:focus-visible {
  transform: translateY(-7px);
  border-color: rgba(var(--accent), 0.55);
  box-shadow: 0 24px 60px -22px rgba(var(--accent), 0.65), inset 0 0 40px rgba(var(--accent), 0.06);
  outline: none;
}
.card-key {
  position: absolute; top: 10px; right: 12px;
  font-size: 8.5px; letter-spacing: 0.1em; color: rgba(255, 255, 255, 0.28);
  border: 1px solid rgba(255, 255, 255, 0.12);
  padding: 2px 5px;
}
.card-icon {
  width: 44px; height: 44px; display: grid; place-items: center;
  font-size: 24px; color: rgb(var(--accent));
  background: radial-gradient(circle, rgba(var(--accent), 0.22), transparent 70%);
  border: 1px solid rgba(var(--accent), 0.32);
  border-radius: 50%;
  text-shadow: 0 0 18px rgba(var(--accent), 0.9);
  margin-bottom: 14px;
  box-shadow: 0 0 24px -6px rgba(var(--accent), 0.5), inset 0 0 16px rgba(var(--accent), 0.1);
}
.card-tag {
  font-size: 7.5px; letter-spacing: 0.3em; color: rgba(var(--accent), 0.85);
  text-transform: uppercase; margin-bottom: 7px;
}
.card-name {
  font-family: var(--sans);
  font-size: 13.5px; font-weight: 700; letter-spacing: 0.08em;
  color: #f2fbff; margin-bottom: 8px;
}
.card-desc { font-size: 10.5px; line-height: 1.55; color: var(--muted); letter-spacing: 0.01em; }
.card-stack {
  margin-top: auto; padding-top: 14px;
  font-size: 8px; letter-spacing: 0.2em; color: rgba(255, 255, 255, 0.3);
}
.card-hint {
  display: flex; align-items: center; justify-content: center; gap: 6px;
  font-family: var(--mono); font-size: 8.5px; letter-spacing: 0.2em; color: var(--faint);
}
.card-hint kbd { font-size: 8.5px; }

/* ----------------------------------------------------------- pause/dead */

.small-panel { width: min(500px, 100%); text-align: center; }
.dead-panel { width: min(620px, 100%); text-align: center; }
.panel-actions { display: flex; justify-content: center; align-items: center; gap: 14px; margin-top: 28px; flex-wrap: wrap; }
.dead-stats {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1px;
  margin-top: 26px;
  background: var(--line-soft);
  border: 1px solid var(--line-soft);
}
.dead-stat {
  display: flex; flex-direction: column; align-items: center; gap: 7px;
  padding: 16px 8px 14px;
  background: rgba(6, 10, 20, 0.72);
}
.dead-stat span { font-family: var(--mono); font-size: 8px; letter-spacing: 0.26em; color: var(--faint); }
.dead-stat b { font-family: var(--mono); font-size: clamp(18px, 2.6vw, 26px); font-weight: 600; color: #f5fcff; font-variant-numeric: tabular-nums; }
.dead-stat:first-child b { color: var(--cyan); text-shadow: 0 0 24px rgba(94, 242, 255, 0.4); }
.record-tag {
  display: inline-flex; align-items: center; gap: 6px;
  margin-top: 16px; padding: 5px 10px;
  font-family: var(--mono); font-size: 8px; letter-spacing: 0.3em;
  color: #0b0710;
  background: linear-gradient(95deg, var(--amber), #ffe0a3);
  opacity: 0; transform: scale(0.9);
  transition: opacity 0.3s ease, transform 0.3s ease;
}
.record-tag.on { opacity: 1; transform: scale(1); animation: tagPulse 2s ease-in-out infinite; }
@keyframes tagPulse { 0%, 100% { box-shadow: 0 0 0 rgba(255, 183, 94, 0); } 50% { box-shadow: 0 0 26px rgba(255, 183, 94, 0.5); } }

/* --------------------------------------------------------------- toast */

.toast {
  position: fixed; z-index: 60; left: 50%; bottom: 40px;
  transform: translate(-50%, 16px);
  padding: 10px 18px;
  font-family: var(--mono); font-size: 9.5px; letter-spacing: 0.18em;
  color: #dff8ff;
  background: rgba(8, 14, 28, 0.9);
  border: 1px solid rgba(94, 242, 255, 0.3);
  box-shadow: 0 12px 40px -10px rgba(0, 0, 0, 0.8);
  opacity: 0; pointer-events: none;
  transition: opacity 0.28s ease, transform 0.28s ease;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }

/* --------------------------------------------------------- responsive */

@media (max-width: 900px) {
  .hud { padding: 14px 16px; gap: 10px; }
  .vitals { width: 210px; }
  .chips { max-width: 210px; }
  .brand-word { font-size: 13px; }
  .chip:nth-child(n + 7) { display: none; }
  .boss-hud { top: 108px; }
  .panel { padding: 30px 26px 26px; }
}

@media (max-width: 700px) {
  .hud { grid-template-columns: 1fr auto; grid-template-rows: auto auto; }
  .hud-left { grid-column: 1; grid-row: 1; gap: 10px; }
  .hud-center {
    grid-column: 1 / -1; grid-row: 2; align-items: flex-start;
    flex-direction: row; align-items: baseline; gap: 8px;
    margin-top: 8px;
  }
  .hud-right { grid-column: 2; grid-row: 1; }
  .brand { display: none; }
  .vitals { width: 170px; }
  .chips { max-width: 170px; }
  .chip:nth-child(n + 4) { display: none; }
  .score-cap { display: none; }
  .score { font-size: 26px; }
  .combo-wrap { margin-top: 0; margin-left: 4px; }
  .combo-bar { width: 34px; }
  .stat-pill { min-width: 56px; padding: 5px 7px; }
  .stat-pill b { font-size: 15px; }
  .stat-pill.dim { display: none; }
  .hud-btns .icon-btn { width: 30px; height: 30px; }
  .boss-hud { top: 104px; width: 64vw; }
  .banner { top: 30%; }
  .banner-text { font-size: 26px; }

  .panel { padding: 26px 20px 24px; clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 18px 100%, 0 calc(100% - 18px)); }
  .title-word { font-size: clamp(50px, 16vw, 76px); }
  .title-sub { letter-spacing: 0.46em; text-indent: 0.46em; }
  .lede { font-size: 12px; margin-top: 16px; }
  .start-actions { margin-top: 22px; gap: 14px; }
  .cta { padding: 14px 22px; font-size: 11px; }
  .best-start b { font-size: 17px; }
  .how { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px 10px; margin-top: 22px; padding-top: 18px; }
  .start-foot { font-size: 7.5px; line-height: 1.6; }
  .overlay { padding: 14px; align-items: center; }

  .cards { grid-template-columns: 1fr; gap: 8px; margin: 18px 0 16px; }
  .card { min-height: 0; flex-direction: row; align-items: center; gap: 12px; padding: 12px 14px; }
  .card-icon { width: 38px; height: 38px; margin: 0; flex: 0 0 38px; font-size: 19px; }
  .card-body { display: flex; flex-direction: column; gap: 4px; }
  .card-tag { margin: 0; }
  .card-name { margin: 0; font-size: 12.5px; }
  .card-desc { font-size: 10px; }
  .card-stack { display: none; }
  .panel-title { font-size: 24px; letter-spacing: 0.1em; }
  .panel-sub { font-size: 11px; }
  .dead-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .dead-stat { padding: 12px 6px; }
}

@media (max-height: 620px) and (min-width: 701px) {
  .panel { padding: 24px 32px 22px; }
  .title-word { font-size: 58px; }
  .lede { display: none; }
  .how { margin-top: 18px; padding-top: 14px; }
  .start-actions { margin-top: 20px; }
  .card { min-height: 176px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.001s !important; transition-duration: 0.001s !important; }
}

content.text:
I used `.card-body` in mobile CSS but renderCards must include it. Now write game.js.

Let me carefully code.

Structure:

```js
const canvas = ...
// UI
const $ = ...
const ui = {...}

// utils
...
// state config
const ARENA = {w:2600,h:1700};
let game = null;
let W,H,DPR;
let cam = {x:ARENA.w/2,y:ARENA.h/2,shake:0,shakeX:0,shakeY:0};
const stars = [];
const motes = [];

// background init
for i<160 stars random in arena with margin...
```

Resize needs to clamp camera.

Drawing background: gradient cached? create once per resize.

```js
let bgGrad = null;
function resize(){
 ...
 buildBgGradient();
}
```

Stars positions based on ARENA but draw with parallax (0.55). With camera translate we can draw stars in world coords with own translate: ctx.save(); ctx.translate(-cam.x*0.55, -cam.y*0.55); draw stars at positions relative... Hmm easier: stars have world positions within arena; draw at x - cam.x*0.7 + (cam.x*0.3)? Let's define parallax = 0.6: screenX = x - cam.x*parallax + ARENA.w*(1-parallax)/2? To keep them covering screen, use a large star field span: positions x in [-500, ARENA.w+500], and screenX = x - cam.x*(1-parallax)? Let's think: normal objects screenX = x - cam.x + W/2. For parallax p (0.5), screenX = (x - cam.x)*p + W/2 + offset. So we just draw in world space with scale? Simplest: save, translate(W/2 + (cam.x)*0.15 - cam.x*0.5 ...). Eh.

Alternative: stars in screen space with slow drift based on camera, generated in screen coordinates normalized, wrapping. Let's do screen-space stars with parallax offsets and twinkle, generated on resize as normalized coordinates:

star = {nx:rand(0,1), ny:rand(0,1), z:rand(.3,1), s:rand(.8,2), tw:rand(0,TAU)}
draw: x = ((star.nx*W - cam.x*star.z*0.15) % W + W) % W; y similarly. This gives subtle drift. Fine and cheap.

Motes (floating dust) in world coordinates for depth near grid: 40 points, drift, drawn small at alpha .2. Could skip.

Grid: step 100 world px. Draw lines:
```js
const step=100;
const left=Math.floor((cam.x-W/2)/step)*step;
for(x=left; x<cam.x+W/2+step; x+=step){ ... }
```
Color per every 5th line brighter.

Arena fill: inside arena draw subtle gradient? The background already dark. Draw arena floor rect with slightly lighter fill + grid clipped to arena. Use ctx.save(); ctx.beginPath(); rect(0,0,ARENA); clip(); fill rgba(8,14,28,.5); grid; restore; then border.

Actually draw grid clipped to arena to emphasize bounds.

Now game creation:

```js
function createGame(){
  return {
    mode:'menu', time:0, score:0, best:loadBest(), kills:0,
    wave:0, waveState:'idle', waveTimer:0, spawnQueue:[], spawnTimer:0, clearTimer:0,
    combo:0, comboTimer:0, comboMax:3.2,
    level:1, xp:0, xpNeed:7, pendingLevels:0,
    stats:{...}, upgrades:{}, choices:[], upgradeVersion:0,
    enemies:[], bullets:[], ebullets:[], orbs:[], particles:[], rings:[], texts:[], portals:[], pickups:[],
    player:null, shake:0, flash:0, hitstop:0, deadTimer:0, hurtVignette:0, newBest:false,
    lastFrame:0
  };
}
```

Player created in resetGame:
```js
function makePlayer(){
 return {x:ARENA.w/2,y:ARENA.h/2,vx:0,vy:0,r:14,hp:100,maxHp:100,shield:50,maxShield:50,shieldDelay:0,
 aim:-Math.PI/2, fireCd:0, dashCd:0, dashTime:0, dashDir:{x:1,y:0}, invuln:0, hurt:0, trail:[], dashHits:new Set(), killsSinceHeal:0,
 recoil:0}
}
```

Stats:
```js
{
  speed: 330, fireInterval: 0.165, damage: 12, bulletSpeed: 1020,
  bullets: 1, spread: 0.075, pierce: 0, crit: 0.06, critMult: 2,
  magnet: 115, dashCd: 2.4, shieldRegen: 9, shieldMax: 50, lifestealEvery: 0, bulletSize: 1, dashBoom: 0
}
```

Upgrades apply modifies stats & player maxes.

UPGRADES definitions with icon characters: '⟡', '✦', '⇶', '➤', '◈', '↻', '✹', '➷', '◎', '⌁', '☄', '❤'... Use text glyphs that render. Safer: '✦','⟡','▲','◈','↺','✚','◎','↯','◉','⌁','☄','♥','⬢'.

Let me define:

```js
const UPGRADES = [
 {id:'rate', name:'HIZLI ATEŞ', tag:'SİLAH', icon:'↯', color:'94,242,255', max:6, desc:'Ateş hızı %16 artar.', apply(s){ s.fireInterval *= 0.84; }},
 {id:'dmg', name:'YOĞUN PLAZMA', tag:'SİLAH', icon:'✦', color:'255,84,190', max:8, desc:'Mermi hasarı %22 artar.', apply(s){ s.damage *= 1.22; }},
 {id:'gun', name:'ÇATALLI NAMLU', tag:'SİLAH', icon:'⇶', color:'170,140,255', max:4, desc:'+1 mermi; hafif yayılım.', apply(s){ s.bullets += 1; s.spread *= 0.94; }},
 {id:'pierce', name:'DELİCİ IŞIN', tag:'SİLAH', icon:'➤', color:'255,183,94', max:3, desc:'Mermiler +1 hedef deler.', apply(s){ s.pierce += 1; }},
 {id:'crit', name:'KRİTİK FREKANS', tag:'SİLAH', icon:'✹', color:'255,120,140', max:5, desc:'Kritik şansı +11%.', apply(s){ s.crit = Math.min(0.8, s.crit + 0.11); }},
 {id:'speed', name:'İTKİ YÜKSELTME', tag:'GÖVDE', icon:'⌁', color:'94,242,255', max:5, desc:'Hareket hızı %11 artar.', apply(s){ s.speed *= 1.11; }},
 {id:'shield', name:'REZONANS KALKANI', tag:'GÖVDE', icon:'◈', color:'94,242,255', max:4, desc:'Kalkan kapasitesi +25.', apply(s,p){ s.shieldMax += 25; p.maxShield = s.shieldMax; p.shield = p.maxShield; }},
 {id:'regen', name:'HIZLI ONARIM', tag:'GÖVDE', icon:'↺', color:'109,255,176', max:4, desc:'Kalkan yenilenmesi %45 hızlanır.', apply(s){ s.shieldRegen *= 1.45; }},
 {id:'hp', name:'GÜÇLENDİRİLMİŞ GÖVDE', tag:'GÖVDE', icon:'✚', color:'109,255,176', max:4, desc:'Maks. can +25, canını iyileştirir.', apply(s,p){ s.maxHp += 25; p.maxHp = s.maxHp; p.hp = Math.min(p.maxHp, p.hp + 25); }},
 {id:'magnet', name:'ÇEKİM ALANI', tag:'SİSTEM', icon:'◎', color:'170,140,255', max:3, desc:'Enerji toplama menzili +70.', apply(s){ s.magnet += 70; }},
 {id:'dash', name:'FAZ ATLAMASI', tag:'SİSTEM', icon:'⤳', color:'94,242,255', max:3, desc:'Atılma beklemesi %22 azalır.', apply(s){ s.dashCd *= 0.78; }},
 {id:'boom', name:'ŞOK DALGASI', tag:'SİSTEM', icon:'☄', color:'255,183,94', max:1, desc:'Atılırken çevrene hasar veren dalga yay.', apply(s){ s.dashBoom = 1; }},
 {id:'vamp', name:'VAMPİR ÇEKİRDEĞİ', tag:'SİSTEM', icon:'♥', color:'255,95,109', max:2, desc:'Her 14 imhada +6 can.', apply(s){ s.vampEvery = (s.vampEvery||0) + 14; }},
 {id:'size', name:'AĞIR ÇEKİRDEK', tag:'SİLAH', icon:'⬢', color:'255,183,94', max:2, desc:'Mermiler %20 büyür, hasar +%8.', apply(s){ s.bulletSize *= 1.2; s.damage *= 1.08; }},
];
```
Vamp: need count tracking; player.killsSinceHeal. On kill if s.vampEvery and killsSinceHeal >= vampEvery → heal 6. Fine.

Note "hp" upgrade maxHp per player: p.maxHp set. Stats maxHp starts 100.

Now the level-up picks need to handle duplicate stacking with max. Fallback if fewer than 3: add heal pseudo-upgrade {id:'heal', name:'ACİL ONARIM', desc:'Canını 40 iyileştir.', icon:'✚', color:'109,255,176', max:Infinity, apply(s,p){p.hp=min(...)}}. Also maybe include as always available option? I'd rather pool always has 3, since 14 upgrades × many stacks. Level cap maybe 30 → total stacks 50; pool available count ~ (6+8+4+3+5+5+4+4+4+3+3+1+2+2)=53. Enough.

Sampling function `sampleChoices` shuffle pool then take 3.

Now input handling and UI wiring.

Start: `startGame()`:
```js
function startGame(){
  audio.unlock();
  game = makeGame();
  game.player = makePlayer();
  game.mode='playing';
  document.body.classList.add('playing');
  document.body.classList.remove('dead');
  hide all overlays
  bindUpgradeChips reset (rebuild)
  startWave(1);
  cam.x=player.x; cam.y=player.y;
  banner('DALGA 1','SÜRÜ YAKLAŞIYOR');
  updateHUD(true);
}
```
`makeGame` uses saved best.

Menu initial: `game = createGame()` with mode 'menu', player at center but not rendered? draw only when mode != menu. Background camera drifts.

Note when game.mode==='menu', no player (null). Draw background with drifting camera.

Return to menu: game.mode='menu'; hide overlays; body classes reset. Camera drift.

Pause:
```js
function togglePause(){
  if(!game) return;
  if(game.mode==='playing'){ game.mode='paused'; ui.pauseScreen.classList.add('show'); }
  else if(game.mode==='paused'){ game.mode='playing'; ui.pauseScreen.classList.remove('show'); }
}
```
Don't allow pause during levelup/dead.

Game over:
```js
function gameOver(){
  if(game.mode!=='playing') return;
  game.mode='dead'; game.deadTimer=0;
  explode(player) ...
  document.body.classList.add('dead');
  document.body.classList.remove('playing'); // HUD stays via body.dead
  newBest check & save
  setTimeout? use deadTimer to show overlay after 0.85s in update.
}
```
Update when mode 'dead': decay particles with 0.4 dt, screen flash.

Show overlay in updateDead when deadTimer>0.9 and not shown.

"Ana ekran" → goMenu(): set game.mode='menu'; hide dead overlay; body classes remove dead/playing; reset camera center.

Retry: startGame().

Now update functions.

update(dt):
```js
game.time += dt;
const p=game.player;
// combo timer
if(game.comboTimer>0){ game.comboTimer-=dt; if(game.comboTimer<=0) game.combo=0; }
// player timers
p.invuln=Math.max(0,p.invuln-dt);
p.hurt=Math.max(0,p.hurt-dt);
p.dashCd=Math.max(0,p.dashCd-dt);
p.shieldDelay=Math.max(0,p.shieldDelay-dt);
if(p.shieldDelay<=0) p.shield += game.stats.shieldRegen*dt; clamp to maxShield
if(p.shield>p.maxShield) p.shield=p.maxShield;

updatePlayerMove(dt);
updateShooting(dt);
updateDash(dt);
updateWaves(dt);
updateEnemies(dt);
updateBullets(dt);
updateEnemyBullets(dt);
updateOrbs(dt);
updatePickups(dt);
updateParticles(dt);
updateRings(dt);
updateTexts(dt);
updatePortals(dt);
// camera
updateCamera(dt);
// shake decay
game.shake = Math.max(0, game.shake - dt*28) ... use exponential
game.flash = Math.max(0, game.flash-dt*2.2)
// hud
updateHUD();
// levelup check
if(game.pendingLevels>0 && game.mode==='playing' && game.enemies... ) openLevelUp();
```

Careful: opening level up inside update then continuing; fine.

updatePlayerMove:
```js
let dx=0,dy=0;
if(keys.has('w')||keys.has('arrowup')) dy -=1;
if(keys.has('s')||keys.has('arrowdown')) dy +=1;
if(keys.has('a')||keys.has('arrowleft')) dx -=1;
if(keys.has('d')||keys.has('arrowright')) dx +=1;
let mag=Math.hypot(dx,dy);
if(mag>0){dx/=mag;dy/=mag;}
if(joy.active && joy.mag>0.12){ dx = joy.x*joy.mag? ... }
```
Store joystick normalized: joy.dx, joy.dy normalized direction and joy.mag 0..1. Movement = dir * mag. Combine keyboard: if keyboard pressed use it, else joystick.

velocity smoothing:
```js
const accel = 1 - Math.pow(0.00005, dt); // very fast? 
```
Better explicit: `const k = 1 - Math.exp(-14*dt)`; p.vx += (tx - p.vx)*k.

Then if p.dashTime>0 override movement (handled in updateDash before? order).

Dash:
```js
function tryDash(){
  if(!game || game.mode!=='playing') return;
  const p=game.player;
  if(p.dashCd>0) return;
  let dx=p.vx, dy=p.vy;
  if(Math.hypot(dx,dy)<40){ dx=Math.cos(p.aim); dy=Math.sin(p.aim); }
  const m=Math.hypot(dx,dy)||1; p.dashDir.x=dx/m; p.dashDir.y=dy/m;
  p.dashTime=0.17; p.invuln=Math.max(p.invuln,0.32); p.dashCd=game.stats.dashCd;
  p.dashHits.clear();
  audio.dash();
  game.shake=Math.max(game.shake,4);
  // ring
  game.rings.push({x:p.x,y:p.y,r:8,maxR:70,life:0.35,max:0.35,color:C.cyan,w:2});
  spark(p.x,p.y,C.cyan,10,180);
}
```
Movement during dash: in updatePlayerMove, if p.dashTime>0: p.vx = dashDir*1250; p.vy likewise; p.dashTime-=dt; spawn trail particle. Position update after.

Wait: decrement dashTime in updatePlayerMove. And dash damage check per frame in updateDash: iterate enemies, if within p.r+22 and not hit → damageEnemy 26 + ring/boom; add hit.

Simplify: merge into updatePlayerMove.

Player trail: push {x,y,a:1} each frame up to 10; decay.

updateShooting:
```js
if(p.dashTime>0) return? can shoot while dashing, fine.
p.fireCd -= dt;
while(p.fireCd<=0){ shoot(); p.fireCd += stats.fireInterval; if(p.fireCd<=0) p.fireCd = stats.fireInterval; }
```
Careful infinite loop if fireInterval small; while with max iterations 2.

shoot():
- fire angle p.aim + tiny random spread.
- count n; fan: offset = (i-(n-1)/2)*stats.spread.
- crit.
- muzzle position p.x + cos*20
- bullet speed with variance 0.97-1.03.
- bullet r 3.6*size.
- pierce stat.
- color crit ? amber : cyan.
- add shake 0.6 (accumulate but cap). Actually game.shake is in px; add 0.5.
- p.recoil = 1.
- audio.shoot() throttled: plays each shot; with 6/s fine.

Maybe auto-aim only on touch or when mouse not moved for 1.8s. Compute in updateAim:

```js
function updateAim(dt){
  const p=game.player;
  const now=game.time;
  let target=null;
  const mouseActive = pointer.active && (now - pointer.lastMove) < 3.0;
  if(mouseActive || !game.touch){
    if(pointer.active){ const w=screenToWorld(pointer.x,pointer.y); target={x:w.x,y:w.y}; }
  }
  if(!target){
    const e=nearestEnemy(p.x,p.y);
    if(e){ const t=dist(p,e)/game.stats.bulletSpeed; target={x:e.x+e.vx*t*0.7, y:e.y+e.vy*t*0.7}; }
  }
  if(!target){ target={x:p.x+Math.cos(p.aim)*100, y:p.y+Math.sin(p.aim)*100}; }
  const want=Math.atan2(target.y-p.y,target.x-p.x);
  p.aim=angleLerp(p.aim,want, 1-Math.exp(-22*dt));
}
```
Hmm mouse aiming should be immediate: use higher responsiveness (1-exp(-30dt)). Auto aim maybe slower (10). Use 26.

But if pointer.active initially false (no mousemove yet), auto-aim. On desktop after moving mouse, pointer.active true. If idle 3s, switches to auto-aim — could feel odd when the player aims manually at empty space; but auto-aim is an accessibility boon. Keep 3s.

`pointer.active` set true on pointermove mouse. `pointer.lastMove = game.time` (needs game; use performance/1000 maybe). Use `performance.now()/1000` global clock `nowSec`.

Simplest: pointer.lastMove = performance.now(); compare performance.now() - lastMove < 2600.

Touch: game.touch true → never use pointer for aim (auto-aim always). But allow touch on right side to aim? skip.

Also allow gamepad? no.

updateEnemies: as planned.

Enemy object:
```js
{
 type, x,y,vx,vy, r, hp,maxHp, speed, dmg, score, xp, color, sides, rot, spin, flash, dead:false,
 behavior, stateT, phase, fireT, wind, dashT, dashDir, hitFlash...
}
```

spawnEnemy(type, x, y) with scaling:
```js
const cfg=TYPES[type];
const w=game.wave;
const hpMul = 1 + (w-1)*0.19 + Math.max(0,w-8)*0.04;
const spMul = 1 + Math.min(0.55, (w-1)*0.035);
const e = {
  type, ...cfg,
  x,y, vx:0, vy:0,
  r: cfg.r * (type==='boss'?1:1.06) - 1,
  hp: cfg.hp*hpMul, maxHp: cfg.hp*hpMul,
  speed: cfg.speed*spMul,
  dmg: cfg.dmg + Math.floor(w/6)*2,
  score: cfg.score,
  color: cfg.color, sides: cfg.sides,
  rot: rnd(0,TAU), spin: cfg.spin ?? rnd(-0.8,0.8),
  flash:0, alive:true,
  fireT: rnd(1.2,2.4),
  windT:0, dashT:0, dashCd:rnd(0.8,2), dashDir:{x:1,y:0},
  phase:0, atkT: rnd(1.5,3),
  level: w
};
```
