function pickSpawnPoint(){
  const p=game.player; let best=null;
  for(let i=0;i<14;i++){
    const a=rnd(0,TAU);
    const rad=Math.max(W,H)*0.58 + rnd(40,160);
    let x=p.x+Math.cos(a)*rad, y=p.y+Math.sin(a)*rad;
    x=clamp(x,70,ARENA.w-70); y=clamp(y,70,ARENA.h-70);
    const d=Math.hypot(x-p.x,y-p.y);
    if(d>Math.min(W,H)*0.42) return {x,y};
    best={x,y};
  }
  return best;
}
```
