Waves queue build:

```js
function buildWave(n){
  const q=[];
  if(n%5===0){
    q.push({type:'boss'});
    const extra = 3 + Math.floor(n/5)*2;
    for(let i=0;i<extra;i++) q.push({type: i%2? 'hunter':'drifter'});
    return {q, boss:true};
  }
  let count = Math.round(4 + n*1.7);
  count = Math.min(count, 30 + Math.floor(n/2));
  const weighted=[];
  weighted.push('drifter','drifter','drifter');
  if(n>=2) weighted.push('hunter','hunter');
  if(n>=3) weighted.push('shooter');
  if(n>=4) weighted.push('brute','hunter');
  if(n>=6) weighted.push('shooter','brute');
  if(n>=8) weighted.push('hunter','brute','shooter');
  for(let i=0;i<count;i++) q.push({type: weighted[Math.floor(Math.random()*weighted.length)]});
  // shuffle lightly so early spawns mixed
  return {q, boss:false};
}
```

