let W = window.innerWidth;
let H = window.innerHeight;
let DPR = 1;
let bgGrad = null;
let visualTime = 0;
let game = null;
let lastAt = 0;
const stars = [];

function resize() {
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  W = window.innerWidth;
  H = window.innerHeight;
  canvas.width = Math.round(W * DPR);
  canvas.height = Math.round(H * DPR);
  canvas.style.width = `${W}px`;
  canvas.style.height = `${H}px`;
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  const g = ctx.createRadialGradient(W * 0.5, H * 0.26, 0, W * 0.5, H * 0.52, Math.max(W, H) * 0.92);
  g.addColorStop(0, "#0c1529");
  g.addColorStop(0.45, "#070b18");
  g.addColorStop(1, "#03040a");
  bgGrad = g;
  buildStars();
}

function buildStars() {
  stars.length = 0;
  const count = clamp(Math.round((W * H) / 11000), 70, 220);
  for (let i = 0; i < count; i += 1) {
    stars.push({
      nx: Math.random(),
      ny: Math.random(),
      z: rnd(0.35, 1),
      s: rnd(0.7, 2.2),
      ph: rnd(0, TAU),
      sp: rnd(0.4, 1.5),
    });
  }
}

function screenToWorld(sx, sy) {
  return { x: cam.x + (sx - W / 2), y: cam.y + (sy - H / 2) };
}

