import { createRequire } from "node:module";
import { readFileSync, mkdirSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

const runtime = process.env.OMGITHUB_PLAYWRIGHT_ROOT || join(homedir(), ".local/share/omgithub-playwright");
const require = createRequire(join(runtime, "package.json"));
const { chromium } = require("playwright");
const config = JSON.parse(readFileSync(join(runtime, "linux.json"), "utf8"));
if (process.platform === "linux") process.env.DISPLAY ||= ":" + readFileSync(join(runtime, "display"), "utf8").trim();

const out = "/tmp/opencode/shots";
mkdirSync(out, { recursive: true });

const browser = await chromium.launch({ ...config.browser?.launchOptions, timeout: 30000 });

async function shot(name, viewport, isMobile, hasTouch, act) {
  const context = await browser.newContext({ viewport, deviceScaleFactor: 1, isMobile, hasTouch });
  const page = await context.newPage();
  page.on("pageerror", (e) => console.error(`[pageerror] ${e.message}`));
  page.on("console", (m) => { if (m.type() === "error") console.error(`[console] ${m.text()}`); });
  await page.goto("http://localhost:3002", { waitUntil: "networkidle" });
  await page.waitForSelector('html[data-ready="true"]');
  await page.waitForTimeout(500);
  if (act) await act(page);
  await page.screenshot({ path: join(out, `${name}.jpg`), type: "jpeg", quality: 78 });
  console.log("saved", name);
  await context.close();
}

await shot("m-start", { width: 1280, height: 800 }, false, false, null);
await shot("m-play", { width: 1280, height: 800 }, false, false, async (page) => {
