Also note drawMenuAmbient still has `ctx.globalCompositeOperation="lighter"` and dust glows (small). Fine.

Now implement fixed timestep loop.

Find `frame` in render.js and replace with accumulator.

Current:
```js
function frame(now) {
  if (!lastAt) lastAt = now;
  const dtRaw = clamp((now - lastAt) / 1000, 0.001, 0.05);
  ...
  if (game.mode === "playing") {
    let dt = dtRaw;
    if (game.hitstop > 0) { ... }
    update(dt);
  } ...
```
Replace with:

```js
let acc = 0;
function frame(now) {
  if (!lastAt) lastAt = now;
  const dtRaw = clamp((now - lastAt) / 1000, 0.001, 0.25);
  lastAt = now;
  visualTime += Math.min(dtRaw, 0.1);
  if (!game) game = createGame("menu");

  if (game.mode === "playing") {
    acc += dtRaw;
    const step = 1 / 60;
    let steps = 0;
    while (acc >= step && steps < 8) {
      let dt = step;
      if (game.hitstop > 0) {
        game.hitstop -= step;
        dt *= 0.15;
      }
      update(dt);
      acc -= step;
      steps += 1;
      if (game.mode !== "playing") { acc = 0; break; }
    }
    if (steps >= 8) acc = 0;
  } else { acc = 0; ... }
```
Need `let acc = 0;` top-level.

Also visualTime: previously += dtRaw up to .05 → slow animation at low fps. Use min(dtRaw, .1).

Menu/dust uses visualTime.

Add glow cap to game.js:
```js
function glow(x,y,r,rgb,alpha=1){
  if(r>180){ alpha *= 180/r; r=180; }
  ...
}
```
